<script setup lang="ts">
import { Play,RefreshCw } from 'lucide-vue-next';import { onMounted,ref } from 'vue';import { message } from 'ant-design-vue';import { platformFlowApi } from '@/services/platformFlowDashboard';import type { PlatformFlowDefinition,PlatformFlowInstance } from '@/types/platformFlowDashboard'
const definitions=ref<PlatformFlowDefinition[]>([]),instances=ref<PlatformFlowInstance[]>([]),loading=ref(false),error=ref('');async function load(){loading.value=true;error.value='';try{[definitions.value,instances.value]=await Promise.all([platformFlowApi.definitions(),platformFlowApi.instances()])}catch(e){error.value=e instanceof Error?e.message:'平台 Flow 加载失败'}finally{loading.value=false}}async function start(flow:PlatformFlowDefinition){try{await platformFlowApi.start(flow.id,{source:'PLATFORM_UI'});message.success('平台 Flow 已完成');await load()}catch(e){error.value=e instanceof Error?e.message:'启动失败'}}onMounted(load)
</script><template><section class="workspace"><header class="workspace-heading"><div><h1>平台 Flow</h1><p>运行授权的平台流程并读回执行结果</p></div><a-button :loading="loading" @click="load"><RefreshCw :size="16"/>刷新</a-button></header><a-alert v-if="error" type="error" show-icon :message="error"/><div class="flow-grid"><article v-for="flow in definitions" :key="flow.id" class="flow-card"><h2>{{ flow.name }}</h2><p>{{ flow.description }}</p><small>{{ flow.code }} · v{{ flow.activeVersionNumber }}</small><a-button type="primary" @click="start(flow)"><Play :size="15"/>运行</a-button></article></div><section class="panel"><h2>我的运行结果</h2><a-table row-key="id" :data-source="instances" :pagination="false"><a-table-column title="实例" data-index="id"/><a-table-column title="版本" data-index="definitionVersion"/><a-table-column title="状态" data-index="status"/><a-table-column title="完成时间" data-index="completedAt"/></a-table></section></section></template><style scoped>.flow-grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(260px,1fr));gap:12px}.flow-card,.panel{display:grid;gap:10px;padding:18px;border:1px solid #dbe2e8;border-radius:8px;background:#fff}.flow-card h2,.flow-card p{margin:0}.panel{margin-top:16px}</style>
